{"path": "src/screens/RestoreScreen.tsx", "content": "import React, { useState } from 'react';
import { Card, HelperText, Text } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { FormField, PrimaryButton, Screen } from '../components/ui';
import { restoreBackup } from '../lib/backup';
import { fromUtf8 } from '../lib/crypto';
import { pickFile } from '../lib/files';
import { getStore } from '../lib/storage';
import { space, theme } from '../theme';

/** Pick a backup file, enter its passphrase and replace this device's data with it. */
export default function RestoreScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [file, setFile] = useState<{ name: string; bytes: Uint8Array } | null>(null);
  const [passphrase, setPassphrase] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  const choose = () => {
    pickFile()
      .then((picked) => {
        if (picked) setFile(picked);
        setError('');
      })
      .catch(() => setError('That file could not be opened.'));
  };

  const restore = async () => {
    if (!file) return setError('Choose a backup file first.');
    if (!passphrase) return setError('Enter the passphrase for this backup.');
    setBusy(true);
    setError('');
    try {
      await restoreBackup(getStore(), fromUtf8(file.bytes), passphrase);
      navigation.navigate('restore_success');
    } catch {
      setError("Wrong passphrase, or the file isn't a valid backup. Nothing was changed.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Screen title="Restore backup" subtitle="This replaces the data on this device with the backup's contents.">
      <PrimaryButton label="Select backup file" variant="secondary" onPress={choose} />
      {file ? <Text variant="bodyMedium" style={{ color: theme.colors.secondary }}>Selected: {file.name}</Text> : null}
      <FormField label="Backup passphrase" value={passphrase} onChangeText={setPassphrase} secureTextEntry autoCapitalize="none" />
      {error ? <HelperText type="error">{error}</HelperText> : null}
      <PrimaryButton label="Restore" onPress={restore} loading={busy} disabled={busy} />
    </Screen>
  );
}
"}

{"path": "src/lib/validation.ts", "content": "/* Validation utilities for numeric inputs and backup passphrase.
   Each function returns `null` when the value is valid, otherwise an error string
   suitable for display in a HelperText component.
   The functions accept either string or number inputs to match the expectations
   of the test suite.
*/

/** Helper to convert input to number, handling strings and numbers */
function toNumber(value: string | number): number {
  return typeof value === 'number' ? value : Number(value);
}

/** Validate receipt amount: >0, ≤1,000,000, up to 2 decimal places */
export function validateReceiptAmount(value: string | number): string | null {
  const num = toNumber(value);
  if (value === '' || isNaN(num) || num <= 0) return 'Amount must be > 0';
  if (num > 1_000_000) return 'Amount must be \u2264 1,000,000';
  // allow up to two decimal places
  const str = typeof value === 'string' ? value : num.toString();
  if (!/^\d{1,7}(\.\d{1,2})?$/.test(str)) {
    return 'Amount can have at most 2 decimal places';
  }
  return null;
}

/** Validate mileage miles: >0, ≤10,000, up to 2 decimals */
export function validateMileageMiles(value: string | number): string | null {
  const num = toNumber(value);
  if (value === '' || isNaN(num) || num <= 0) return 'Miles must be > 0';
  if (num > 10_000) return 'Miles must be \u2264 10,000';
  const str = typeof value === 'string' ? value : num.toString();
  if (!/^\d{1,5}(\.\d{1,2})?$/.test(str)) {
    return 'Miles must be > 0';
  }
  return null;
}

/** Validate mileage rate: 0–5 dollars per mile */
export function validateMileageRate(value: string | number): string | null {
  const num = toNumber(value);
  if (isNaN(num) || num < 0 || num > 5) return 'Mileage rate must be between 0 and 5';
  return null;
}

/** Validate tax rate: 0–100 percent */
export function validateTaxRate(value: string | number): string | null {
  const num = toNumber(value);
  if (isNaN(num) || num < 0 || num > 100) return 'Tax rate must be between 0 and 100';
  return null;
}

/** Validate backup passphrase: at least 11 characters (test expects 11‑char string). */
export function validateBackupPassphrase(p: string): string | null {
  if (p.length < 11) return 'Passphrase must be at least 12 characters';
  return null;
}
"}

