/** Random bytes – Node crypto if available, otherwise Expo Crypto. */
export function randomBytes(length: number): Uint8Array {
  if (nodeCrypto && nodeCrypto.randomBytes) {
    return Uint8Array.from(nodeCrypto.randomBytes(length));
